{"command": "cd /workspace && cat > work/song.py <<'EOF'
#!/usr/bin/env python3
"""Patterns for NEBULA KEYGEN. Appends to instr.json calls -> song.json"""
import json

SEMI = {'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
def note(n):
    name, oct_ = n[:-1], int(n[-1])
    return (oct_+1)*12 + SEMI[name] + 1

calls = json.load(open('work/instr.json'))
def call(tool, **kw): calls.append({'name':tool,'arguments':kw})

# song header first (module_new must be first call though!) - we reorder: prepend
head = [
 {'name':'module_new','arguments':{'channels':8,'name':'NEBULA KEYGEN'}},
 {'name':'song_set','arguments':{'bpm':150,'speed':6}},
]
calls = head + calls

NPAT = 8
for p in range(NPAT):
    call('pattern_set_length', pattern=p, rows=64)
    call('order_set', position=p, pattern=p)

CH = {'lead':0,'echo':1,'bass':2,'arp':3,'pad':3,'kick':4,'snare':5,'hat':6,'fx':7}

def cell(pat,row,ch,note_s=None,instr=None,vol=None,fx=None,fxp=None):
    a={'pattern':pat,'row':row,'channel':ch}
    if note_s is not None: a['note']=note_s if isinstance(note_s,str) else note_s
    if instr: a['instrument']=instr
    if vol is not None: a['volume']=vol
    if fx is not None: a['effect']=fx
    if fxp is not None: a['effect_param']=fxp
    call('pattern_set_cell',**a)

# ---------------- LEAD melodies ----------------
vib = (0x0, 0x45)   # vibrato: speed4 depth5

def lead_phrase(p, notes, vols=None, vib_from=None):
    for i,(row,nt) in enumerate(notes):
        fx,fxp = (vib if (vib_from is not None and i>=vib_from) else (None,None))
        v = 0x50
        cell(p,row,CH['lead'],nt,1,v,fx,fxp)

# P1 theme A phrase 1
P1=[(0,'A4'),(2,'C5'),(4,'E5'),(6,'A5'),(8,'G5'),(10,'E5'),(12,'D5'),(14,'E5'),
    (16,'F5'),(18,'A5'),(20,'C6'),(22,'A5'),(24,'G5'),(26,'F5'),(28,'E5'),(30,'F5'),
    (32,'G5'),(34,'A5'),(36,'E5'),(38,'C5'),(40,'D5'),(42,'E5'),(44,'C5'),(46,'E5'),
    (48,'D5'),(50,'B4'),(52,'G4'),(54,'D5'),(56,'E5'),(58,'D5'),(60,'B4'),(62,'D5')]
# P2 phrase 2 (answer, higher)
P2=[(0,'C5'),(2,'E5'),(4,'G5'),(6,'C6'),(8,'B5'),(10,'G5'),(12,'E5'),(14,'G5'),
    (16,'A5'),(18,'C6'),(20,'E6'),(22,'C6'),(24,'A5'),(26,'E5'),(28,'F5'),(30,'A5'),
    (32,'E5'),(34,'G5'),(36,'B5'),(38,'E5'),(40,'G5'),(42,'B5'),(44,'E5'),(46,'G5'),
    (48,'B5'),(50,'D6'),(52,'B5'),(54,'G5'),(56,'E5'),(58,'G5'),(60,'B5'),(61,'G5'),(62,'B5')]
# P3 B-theme low, held
P3=[(0,'F4'),(4,'A4'),(8,'C5'),(12,'A4'),
    (16,'G4'),(20,'B4'),(24,'D5'),(28,'B4'),
    (32,'A4'),(36,'C5'),(40,'E5'),(44,'A5'),(48,'G5'),(52,'E5'),(56,'C5'),(60,'E5')]
# P4 B-theme climax with runs
P4=[(0,'A4'),(2,'C5'),(4,'F5'),(6,'C5'),(8,'A5'),(10,'F5'),(12,'C5'),(14,'F5'),
    (16,'G4'),(18,'B4'),(20,'G5'),(22,'B4'),(24,'B5'),(26,'G5'),(28,'B4'),(30,'D5'),
    (32,'C5'),(34,'E5'),(36,'A5'),(38,'E5'),(40,'C6'),(42,'A5'),(44,'E5'),(46,'A5'),
    (48,'B5'),(50,'G5'),(51,'E5'),(52,'B5'),(54,'D6'),(56,'E6'),(58,'B5'),(60,'G5'),(62,'B5')]
# P5 theme A reprise var + descent to loop
P5=[(0,'A5'),(2,'G5'),(4,'E5'),(6,'A5'),(8,'C6'),(10,'A5'),(12,'G5'),(14,'E5'),
    (16,'F5'),(18,'A5'),(20,'C6'),(22,'A5'),(24,'G5'),(26,'F5'),(28,'E5'),(30,'F5'),
    (32,'E5'),(34,'G5'),(36,'E5'),(38,'C5'),(40,'E5'),(42,'G5'),(44,'A5'),(45,'G5'),(46,'A5'),
    (48,'B5'),(50,'G5'),(52,'E5'),(54,'D5'),(56,'E5'),(58,'C5'),(60,'A4'),(62,'E5')]
# P0 intro: only lead tease rows 56-63
P0=[(56,'A4'),(58,'C5'),(60,'E5'),(62,'A5')]
LEADS=[P0,P1,P2,P3,P4,P5]
for p,notes in enumerate(LEADS):
    for row,nt in notes:
        a={'pattern':p,'row':row,'channel':0,'note':nt,'instrument':1,'volume':0x50}
        # vibrato on held notes (next note >2 rows away)
        calls.append({'name':'pattern_set_cell','arguments':a})
# add vibrato fx on sustained rows (note kept ringing): place 45x where no note
for p,notes in enumerate(LEADS):
    occ={r for r,_ in notes}
    for row,nt in notes:
        for rr in (row+1,row+2):
            if rr<64 and rr not in occ:
                nxt = min([r2 for r2,_ in notes if r2>row], default=64)
                if rr < nxt-1:
                    cell(p,rr,0,None,None,None,0x0,0x45)

# echo channel: copy lead shifted +3 rows, vol 0x29 (26), instr 2
for p,notes in enumerate(LEADS):
    occ={r for r,_ in notes}
    for row,nt in notes:
        if row+3 < 64 and (row+3) not in occ:
            cell(p,row+3,CH['echo'],nt,2,0x29)
# sustain the echo too? echo notes ring anyway until next echo; good.

# ---------------- BASS ----------------
# chords per pattern: 4 x 16 rows
CHORDS = {
 0:['A','A','F','G'],
 1:['A','F','C','G'],
 2:['A','F','C','G'],
 3:['F','G','A','E'],
 4:['F','G','A','E'],
 5:['A','F','C','G'],
}
BASS_PAT={ 'A':'A2','F':'F2','C':'C3','G':'G2','D':'D3','E':'E2'}
def bass_prog(p, style='drive'):
    chd = CHORDS[p]
    for bar in range(4):
        r = BASS_PAT[chd[bar]]
        up = chr(r[0]).replace('#','#')
        root = r
        octup = root[0]+('' if len(root)<3 else '#')+str(int(root[-1])+1)
        if style=='drive':
            seq=[(0,root),(2,octup),(4,root),(6,octup),(8,root),(10,octup),(12,root),(14,octup)]
        elif style=='calm':
            seq=[(0,root),(4,root),(8,octup),(10,root),(12,root)]
        elif style=='intro':
            seq=[(0,root),(8,root),(10,root),(14,octup)] if bar>=2 else [(0,root),(8,root)]
        for off,nt in seq:
            v = 0x50 if off%4==0 else 0x40
            cell(p,bar*16+off,CH['bass'],nt,3,v)

bass_prog(0,'intro')
for p in (1,2,5): bass_prog(p,'drive')
for p in (3,4): bass_prog(p,'calm')

# ---------------- ARP (16th chord tones) ----------------
ARP4={ 'A':['A3','C4','E4','A4'], 'F':['F3','A3','C4','F4'], 'C':['C4','E4','G4','C5'],
       'G':['G3','B3','D4','G4'], 'E':['E3','G#3','B3','E4'], 'D':['D3','F3','A3','D4']}
def arp(p, rows=range(64), vol=0x38, dense=True):
    chd=CHORDS[p]
    for r in rows:
        bar=r//16; tones=ARP4[chd[bar]]
        if dense:
            seq = tones if (r//4)%2==0 else tones[::-1]
            nt = seq[r%4]
        else:
            nt = tones[(r//4)%4] if r%4==0 else None
        if nt:
            cell(p,r,CH['arp'],nt,4,vol)
arp(0, range(0,64), 0x34)
for p in (1,2,5): arp(p, range(64), 0x30)
# P3,P4 sparser: quarter notes + turn
for p in (3,4):
    chd=CHORDS[p]
    for r in range(64):
        if r%4==0:
            tones=ARP4[chd[r//16]]
            cell(p,r,CH['arp'],tones[(r//4)%4],4,0x30)
        elif r%16==14:
            cell(p,r,CH['arp'],ARP4[chd[r//16]][3],4,0x28)

# ---------------- PAD (ch3 too? ch3 busy with arp) ----------------
# put pad on ch7 for P3/P4 roots+5th
PADCH={ 'F':['F3','C4'],'G':['G3','D4'],'A':['A3','E4'],'E':['E3','B3'],'Am':['A3','E4']}
for p in (3,4):
    chd=CHORDS[p]
    for bar in range(4):
        c=chd[bar]; tns=PADCH[c]
        for nt in tns:
            cell(p,bar*16,CH['fx'],nt,10,0x30)
# P5 pads on last 2 bars? keep fx ch for riser; skip

# ---------------- DRUMS ----------------
def kick(p,rows):
    for r in rows: cell(p,r,CH['kick'],'C-4',5,0x50)
def snare(p,rows,vol=0x3C):
    for r in rows: cell(p,r,CH['snare'],'C-4',6,vol)
def hat(p,rows,vol=0x34,instr=7,nt='C-5'):
    for r in rows: cell(p,r,CH['hat'],nt,instr,vol)
def fx(p,row,instr,nt='C-5',vol=0x30):
