import struct
d=open('submission/tune.xm','rb').read()
off=60+struct.unpack('<I',d[60:64])[0]
names='C- C# D- D# E- F- F# G- G# A- A# B-'.split()
def nm(b): return names[(b-1)%12]+str((b-1)//12)
for p in range(2):
    hl,pt,rows,ds=struct.unpack('<IBHH',d[off:off+9])
    pd=d[off+hl:off+hl+ds]; i=0
    print('--- pattern',p)
    for r in range(rows):
        cells=[]
        for c in range(8):
            b=pd[i]; i+=1
            vals=[0,0,0,0,0]
            if b&0x80:
                for k in range(5):
                    if b&(1<<k): vals[k]=pd[i]; i+=1
            else:
                vals=[b]+list(pd[i:i+4]); i+=4
            if any(vals): cells.append((c,nm(vals[0]) if vals[0] else '--',vals[1],hex(vals[2]),vals[3],vals[4]))
        if r<12 or (p==0 and r>=56): print(r,cells)
    off+=hl+ds
EOF"}

